CREATE TABLE "exercises" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "name" TEXT NOT NULL, "variation" TEXT NULL, "equipment" TEXT NULL, "target_muscles" TEXT NULL, "note" TEXT NULL, "instruction_source" TEXT NULL, "catalog_id" TEXT NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "workout_templates" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "name" TEXT NOT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "template_exercises" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "template_id" TEXT NOT NULL REFERENCES workout_templates (id) ON DELETE CASCADE, "exercise_id" TEXT NOT NULL REFERENCES exercises (id), "position" INTEGER NOT NULL, "target_sets" INTEGER NULL, "target_reps" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "workout_sessions" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "template_id" TEXT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL, "started_at" TEXT NOT NULL, "ended_at" TEXT NULL, "paused_ms" INTEGER NOT NULL DEFAULT 0, "paused_at" TEXT NULL, "rest_started_at" TEXT NULL, "rest_target_sec" INTEGER NULL, "utc_offset_minutes" INTEGER NOT NULL, "time_zone_name" TEXT NOT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "session_exercises" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "session_id" TEXT NOT NULL REFERENCES workout_sessions (id) ON DELETE CASCADE, "exercise_id" TEXT NOT NULL REFERENCES exercises (id), "position" INTEGER NOT NULL, "superset_group" TEXT NULL, "skipped" INTEGER NOT NULL DEFAULT 0 CHECK ("skipped" IN (0, 1)), "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "set_entries" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "session_exercise_id" TEXT NOT NULL REFERENCES session_exercises (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "set_type" TEXT NOT NULL, "reps" INTEGER NULL, "load" REAL NULL, "load_unit" TEXT NULL, "duration_sec" INTEGER NULL, "distance" REAL NULL, "distance_unit" TEXT NULL, "rest_sec" INTEGER NULL, "effort" REAL NULL, "note" TEXT NULL, "completed" INTEGER NOT NULL DEFAULT 0 CHECK ("completed" IN (0, 1)), "completed_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "foods" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "name" TEXT NOT NULL, "brand" TEXT NULL, "serving_amount" REAL NULL, "serving_unit" TEXT NULL, "energy_kcal" REAL NULL, "protein_g" REAL NULL, "carbs_g" REAL NULL, "fat_g" REAL NULL, "is_estimate" INTEGER NOT NULL DEFAULT 0 CHECK ("is_estimate" IN (0, 1)), "source" TEXT NOT NULL, "source_checked_at" TEXT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "meal_slots" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "name" TEXT NOT NULL, "position" INTEGER NOT NULL, "usual_minute" INTEGER NULL, "kind" TEXT NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "meal_entries" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "day" TEXT NOT NULL, "slot_id" TEXT NOT NULL REFERENCES meal_slots (id), "food_id" TEXT NULL, "name" TEXT NOT NULL, "brand" TEXT NULL, "serving_amount" REAL NULL, "serving_unit" TEXT NULL, "energy_kcal" REAL NULL, "protein_g" REAL NULL, "carbs_g" REAL NULL, "fat_g" REAL NULL, "amount" REAL NULL, "amount_unit" TEXT NULL, "is_estimate" INTEGER NOT NULL DEFAULT 0 CHECK ("is_estimate" IN (0, 1)), "source" TEXT NOT NULL, "source_checked_at" TEXT NULL, "status" TEXT NOT NULL, "eaten_at" TEXT NULL, "time_zone_name" TEXT NOT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));